def crack_safe(a, b, c, d):
    if a == b == c == d == 1:
        return []

    if a % 2 == 0 and b % 2 == 0:
        return ["/1"] + crack_safe(a // 2, b // 2, c, d)
    elif b % 2 == 0 and c % 2 == 0:
        return ["/2"] + crack_safe(a, b // 2, c // 2, d)
    elif c % 2 == 0 and d % 2 == 0:
